{"dependencies": [], "lesson": "unique survivor for this source: upsert DO UPDATE conflict handling, channel = main changes() (last statement count), no trigger; savepoint-initiated transactions commit on release of outermost savepoint", "scope": "disposable SQLite source; simulate 3x3x2 family with native savepoint/transaction semantics, filter by calibration receipts, answer only when all survivors agree", "source": "def simulate(cand, actions):
    committed = {}
    conns = {}
    for name in ["main", "other"]:
        conns[name] = {"open": False, "pending": {}, "sp": [], "init": False, "total": 0}
    open_conn = None
    main_last = 0
    for a in actions:
        op = a.get("op")
        if op == "begin":
            if open_conn is None:
                c = a.get("connection", "main")
                if c != "other":
                    c = "main"
                open_conn = c
                st = conns[c]
                st["open"] = True
                st["pending"] = {}
                st["sp"] = []
                st["init"] = False
        elif op == "commit":
            if open_conn is not None:
                st = conns[open_conn]
                pend = st["pending"]
                for k in pend:
                    if pend[k] is None:
                        if k in committed:
                            committed.pop(k)
                    else:
                        committed[k] = pend[k]
                st["open"] = False
                st["pending"] = {}
                st["sp"] = []
                st["init"] = False
                open_conn = None
        elif op == "rollback":
            if open_conn is not None:
                st = conns[open_conn]
                st["open"] = False
                st["pending"] = {}
                st["sp"] = []
                st["init"] = False
                open_conn = None
        elif op == "savepoint":
            if open_conn is not None:
                c = open_conn
            else:
                c = a.get("connection", "main")
                if c != "other":
                    c = "main"
            st = conns[c]
            if not st["open"]:
                st["open"] = True
                st["pending"] = {}
                st["sp"] = []
                st["init"] = True
                open_conn = c
            st["sp"].append([a.get("name"), st["pending"].copy()])
        elif op == "rollback_to":
            if open_conn is not None:
                c = open_conn
            else:
                c = a.get("connection", "main")
                if c != "other":
                    c = "main"
            st = conns[c]
            nm = a.get("name")
            idx = -1
            for i in range(len(st["sp"])):
                if st["sp"][i][0] == nm:
                    idx = i
            if idx >= 0:
                snap = st["sp"][idx][1]
                st["pending"] = snap.copy()
                newsp = []
                for i in range(idx + 1):
                    newsp.append(st["sp"][i])
                st["sp"] = newsp
        elif op == "release":
            if open_conn is not None:
                c = open_conn
            else:
                c = a.get("connection", "main")
                if c != "other":
                    c = "main"
            st = conns[c]
            nm = a.get("name")
            idx = -1
            for i in range(len(st["sp"])):
                if st["sp"][i][0] == nm:
                    idx = i
            if idx >= 0:
                newsp = []
                for i in range(idx):
                    newsp.append(st["sp"][i])
                st["sp"] = newsp
                if len(newsp) == 0 and st["init"] and st["open"]:
                    pend = st["pending"]
                    for k in pend:
                        if pend[k] is None:
                            if k in committed:
                                committed.pop(k)
                        else:
                            committed[k] = pend[k]
                    st["open"] = False
                    st["pending"] = {}
                    st["init"] = False
                    open_conn = None
        else:
            if open_conn is not None:
                conn = open_conn
            else:
                conn = a.get("connection", "main")
                if conn != "other":
                    conn = "main"
            st = conns[conn]
            key = a.get("key")
            intxn = st["open"]
            if intxn:
                store = st["pending"]
                if key in store:
                    exists = store[key] is not None
                else:
                    exists = key in committed
            else:
                store = committed
                exists = key in committed
            ch = 0
            fired = False
            if op == "put":
                v = a.get("value")
                if exists:
                    if cand["conflict"] == "ignore":
                        ch = 0
                    elif cand["conflict"] == "replace":
                        store[key] = v
                        ch = 2
                        fired = True
                    else:
                        store[key] = v
                        ch = 1
                else:
                    store[key] = v
                    ch = 1
                    fired = True
            elif op == "update":
                if exists:
                    store[key] = a.get("value")
                    ch = 1
            elif op == "delete":
                if exists:
                    if intxn:
                        store[key] = None
                    else:
                        store.pop(key)
                    ch = 1
            extra = 0
            if fired and cand["trigger"]:
                extra = 1
            st["total"] = st["total"] + ch + extra
            if conn == "main":
                main_last = ch + extra
    if cand["channel"] == "changes":
        chan = main_last
    elif cand["channel"] == "total_main":
        chan = conns["main"]["total"]
    else:
        chan = conns["main"]["total"] + conns["other"]["total"]
    s = 0
    for v in committed.values():
        s = s + v
    return {"channel": chan, "count": len(committed), "sum": s}


def investigate(context, acquire):
    hist = acquire("history")
    sid = context.get("source_id")
    cands = []
    for conflict in ["ignore", "replace", "upsert"]:
        for channel in ["changes", "total_main", "both"]:
            for trig in [False, True]:
                cand = {"conflict": conflict, "channel": channel, "trigger": trig}
                ok = True
                for r in hist:
                    if r.get("source_id") != sid:
                        continue
                    obs = r.get("observed")
                    res = simulate(cand, r.get("actions", []))
                    if res["channel"] != obs.get("channel"):
                        ok = False
                    if res["count"] != obs.get("committed_count"):
                        ok = False
                    if res["sum"] != obs.get("committed_sum"):
                        ok = False
                if ok:
                    cands.append(cand)
    if len(cands) == 0:
        return {"value": None, "unresolved": True}
    goal = context.get("goal")
    vals = []
    for cand in cands:
        res = simulate(cand, context.get("actions", []))
        if goal == "channel":
            vals.append(res["channel"])
        elif goal == "committed_count":
            vals.append(res["count"])
        else:
            vals.append(res["sum"])
    first = vals[0]
    for v in vals:
        if v != first:
            return {"value": None, "unresolved": True}
    return {"value": first, "unresolved": False}
